from __future__ import annotations

import platform
import subprocess

from secretscan.model import Listener, Module, ModuleStatus


def _classify_exposure(addr: str) -> str:
    if addr in ("*", "0.0.0.0", "::", ""):
        return "all interfaces"
    if addr in ("127.0.0.1", "::1", "localhost"):
        return "localhost only"
    return f"specific interface ({addr})"


def _split_host_port(name: str) -> tuple[str, str] | None:
    if name.startswith("["):
        end = name.find("]")
        if end == -1:
            return None
        addr = name[1:end]
        rest = name[end + 1 :]
        if not rest.startswith(":"):
            return None
        port = rest[1:]
    else:
        idx = name.rfind(":")
        if idx == -1:
            return None
        addr = name[:idx]
        port = name[idx + 1 :]
    try:
        int(port)
    except ValueError:
        return None
    return addr, port


def _parse_lsof(output: str, proto: str) -> list[Listener]:
    listeners: list[Listener] = []
    for line in output.splitlines():
        fields = line.split()
        if len(fields) < 2 or fields[0] == "COMMAND":
            continue
        name = fields[-1]
        if name == "(LISTEN)":
            if len(fields) < 3:
                continue
            name = fields[-2]
        if "->" in name:
            continue
        parsed = _split_host_port(name)
        if not parsed:
            continue
        addr, port = parsed
        listeners.append(Listener(
            proto=proto,
            address=addr,
            port=port,
            process_name=fields[0],
            pid=fields[1],
            exposure=_classify_exposure(addr),
        ))
    return listeners


def _parse_netstat_windows(output: str) -> list[Listener]:
    listeners: list[Listener] = []
    for line in output.splitlines():
        line = line.strip()
        fields = line.split()
        if len(fields) < 4:
            continue
        proto_raw = fields[0].lower()
        if proto_raw not in ("tcp", "udp"):
            continue
        local = fields[1]
        state = fields[3] if len(fields) > 3 else ""
        if proto_raw == "tcp" and state != "LISTENING":
            continue

        parsed = _split_host_port(local)
        if not parsed:
            continue
        addr, port = parsed
        pid = fields[4] if len(fields) > 4 else ""
        listeners.append(Listener(
            proto=proto_raw,
            address=addr,
            port=port,
            pid=pid,
            exposure=_classify_exposure(addr),
        ))
    return listeners


def _dedup_listeners(raw: list[Listener]) -> list[Listener]:
    seen: dict[tuple, int] = {}
    out: list[Listener] = []
    for l in raw:
        key = (l.proto, l.address, l.port, l.pid)
        if key in seen:
            out[seen[key]].sockets += 1
            continue
        l.sockets = 1
        seen[key] = len(out)
        out.append(l)
    return out


def network_scan() -> tuple[list[Listener], ModuleStatus]:
    status = ModuleStatus(module=Module.NETWORK)
    raw: list[Listener] = []

    system = platform.system()

    if system == "Windows":
        try:
            result = subprocess.run(
                ["netstat", "-ano"],
                capture_output=True, text=True, timeout=15,
            )
            if result.returncode == 0:
                raw.extend(_parse_netstat_windows(result.stdout))
        except (subprocess.SubprocessError, FileNotFoundError):
            pass
    else:
        try:
            tcp = subprocess.run(
                ["lsof", "-nP", "-iTCP", "-sTCP:LISTEN"],
                capture_output=True, text=True, timeout=15,
            )
            if tcp.returncode == 0:
                raw.extend(_parse_lsof(tcp.stdout, "tcp"))
        except (subprocess.SubprocessError, FileNotFoundError):
            pass

        try:
            udp = subprocess.run(
                ["lsof", "-nP", "-iUDP"],
                capture_output=True, text=True, timeout=15,
            )
            if udp.returncode == 0:
                raw.extend(_parse_lsof(udp.stdout, "udp"))
        except (subprocess.SubprocessError, FileNotFoundError):
            pass

    listeners = _dedup_listeners(raw)
    status.attempted = len(listeners)
    status.accessed = len(listeners)
    status.note = (
        "only sockets visible to the current user are enumerated; "
        "root-owned sockets require sudo, which this tool never invokes"
    )
    return listeners, status
